"""Exercise engine — orchestrates TimeManager, EventScheduler (injects), IssueManager (defects).

Domain terms: "inject" = event, "defect" = issue. See AGENTS.md terminology mapping.
"""

from __future__ import annotations

import asyncio
import time as _time_mod
from collections.abc import Awaitable, Callable
from enum import StrEnum

from engine.decision_manager import DecisionManager
from engine.engine_config import (  # noqa: F401 — re-exported
    TICK_INTERVAL_S,
    DecisionTemplate,
    EngineConfig,
    ScenarioContext,
)
from engine.event_scheduler import EventLifecycle, EventScheduler, EventType
from engine.game_modes.protocol import GameMode
from engine.issue_manager import IssueManager
from engine.state_changes import (
    DecisionOpened,
    DecisionOptionSnapshot,
    EngineSnapshot,
    PhaseChange,
    StateChange,
    SystemStateChange,
)
from engine.system_manager import SystemManager
from engine.time_manager import TimeManager


class EngineStateError(RuntimeError):
    """Raised when an engine lifecycle method is called in an invalid phase."""


class EnginePhase(StrEnum):
    SETUP = "setup"
    BRIEFING = "briefing"
    RUNNING = "running"
    PAUSED = "paused"
    COMPLETED = "completed"


class ExerciseEngine:
    """Runtime engine for a single exercise session."""

    def __init__(
        self,
        config: EngineConfig,
        on_state_change: Callable[[list[StateChange]], Awaitable[None]] | None = None,
    ) -> None:
        self._config = config
        self._phase = EnginePhase.SETUP
        self._time = TimeManager(factor=config.time_factor)
        self._events = EventScheduler()
        self._issues = IssueManager()
        self._systems = SystemManager()
        self._decisions = DecisionManager()
        self._tick_task: asyncio.Task | None = None  # type: ignore[type-arg]
        self._timeout_task: asyncio.Task | None = None  # type: ignore[type-arg]
        self._on_state_change = on_state_change

        self._events.load_events(config.events)
        self._issues.load_issues(config.issues)
        self._systems.load_systems(list(config.initial_system_states))

    @property
    def phase(self) -> EnginePhase:
        return self._phase

    @property
    def time_manager(self) -> TimeManager:
        return self._time

    @property
    def event_scheduler(self) -> EventScheduler:
        return self._events

    @property
    def issue_manager(self) -> IssueManager:
        return self._issues

    @property
    def system_manager(self) -> SystemManager:
        return self._systems

    @property
    def decision_manager(self) -> DecisionManager:
        return self._decisions

    @property
    def config(self) -> EngineConfig:
        return self._config

    @property
    def game_mode(self) -> GameMode:
        return self._config.game_mode

    async def start(self) -> PhaseChange:
        if self._phase not in {EnginePhase.SETUP}:
            raise EngineStateError(f"Cannot start from {self._phase}")
        self._phase = EnginePhase.BRIEFING
        return self._phase_change("started")

    async def begin(self) -> PhaseChange:
        """Transition BRIEFING → RUNNING: player has read the briefing."""
        if self._phase != EnginePhase.BRIEFING:
            raise EngineStateError(f"Cannot begin from {self._phase}")
        self._phase = EnginePhase.RUNNING
        self._time.start()
        self._start_tick_loop()
        return self._phase_change("begun")

    async def pause(self) -> PhaseChange:
        if self._phase != EnginePhase.RUNNING:
            raise EngineStateError(f"Cannot pause from {self._phase}")
        self._phase = EnginePhase.PAUSED
        self._time.pause()
        self._stop_tick_loop()
        return self._phase_change("paused")

    async def resume(self) -> PhaseChange:
        if self._phase != EnginePhase.PAUSED:
            raise EngineStateError(f"Cannot resume from {self._phase}")
        self._phase = EnginePhase.RUNNING
        self._time.start()
        self._start_tick_loop()
        return self._phase_change("started")

    async def complete(self) -> PhaseChange:
        if self._phase in {EnginePhase.COMPLETED, EnginePhase.SETUP}:
            raise EngineStateError(f"Cannot complete from {self._phase}")
        self._phase = EnginePhase.COMPLETED
        self._time.pause()
        self._stop_tick_loop()
        self._stop_timeout_monitor()
        return self._phase_change("completed")

    async def reset(self) -> PhaseChange:
        self._stop_tick_loop()
        self._stop_timeout_monitor()
        self._phase = EnginePhase.SETUP
        self._time.reset()
        self._events.load_events(self._config.events)
        self._issues.load_issues(self._config.issues)
        self._systems.load_systems(list(self._config.initial_system_states))
        self._decisions.clear()
        return self._phase_change("reset")

    def set_speed(self, factor: float) -> StateChange:
        self._time.factor = factor
        return {"type": "speed_change", "factor": factor}

    async def tick(self) -> list[StateChange]:
        """Advance time, check triggers, return state changes."""
        changes: list[StateChange] = []
        self._time.tick()
        pt = self._time.play_time_ms

        event_changes = self._events.tick(pt)
        changes.extend(event_changes)

        decision_changes = self._handle_decision_events(event_changes, pt)
        changes.extend(decision_changes)

        completed_events = {
            eid
            for eid, ev in self._events.events.items()
            if ev.lifecycle == EventLifecycle.COMPLETED
        }

        for change in event_changes:
            if change.get("action") == "completed":
                event_id = change["event_id"]
                issue_changes = self._issues.activate_by_event(event_id, pt)
                changes.extend(issue_changes)

        issue_changes = self._issues.tick(pt, completed_events)
        changes.extend(issue_changes)

        if changes and self._on_state_change:
            await self._on_state_change(changes)
        return changes

    def snapshot(self) -> EngineSnapshot:
        """Full state snapshot for client sync."""
        return EngineSnapshot(
            exercise_id=self._config.exercise_id,
            title=self._config.title,
            phase=self._phase.value,
            time=self._time.snapshot(),
            events=self._events.snapshot(),
            issues=self._issues.snapshot(),
            decisions=self._decisions.snapshot(),
            score=self._config.game_mode.snapshot(),
            systems=self._systems.snapshot(),
        )

    def _handle_decision_events(
        self,
        event_changes: list[StateChange],
        pt: float,
    ) -> list[DecisionOpened]:
        changes: list[DecisionOpened] = []
        for change in event_changes:
            if change.get("action") != "started":
                continue
            event_id = change["event_id"]
            event = self._events.events.get(event_id)
            if event is None or event.event_type != EventType.DECISION:
                continue
            t = self.find_decision_template(event_id)
            timeout_ms = t.timeout_ms if t else 0.0
            changes.append(
                self._decisions.open_decision(
                    id=t.id if t else event_id,
                    event_id=event_id,
                    issue_id=t.issue_id if t else None,
                    title=t.title if t else event.title,
                    description=t.description if t else event.description,
                    question_type=t.question_type if t else "free_text",
                    options=t.options if t else [],
                    completion_mode=t.completion_mode if t else "first_response",
                    target_roles=t.target_roles if t else [],
                    timeout_ms=timeout_ms,
                    max_selections=t.max_selections if t else None,
                    current_pt_ms=pt,
                )
            )
            if self._config.game_mode.should_pause_on_decision():
                self._phase = EnginePhase.PAUSED
                self._time.pause()
                self._stop_tick_loop()
            if timeout_ms > 0:
                self._start_timeout_monitor()
        return changes

    def find_decision_template(self, event_id: str) -> DecisionTemplate | None:
        return next((dt for dt in self._config.decision_templates if dt.id == event_id), None)

    def _start_tick_loop(self) -> None:
        if self._tick_task is None or self._tick_task.done():
            self._tick_task = asyncio.create_task(self._tick_loop())

    def _stop_tick_loop(self) -> None:
        if self._tick_task and not self._tick_task.done():
            self._tick_task.cancel()
            self._tick_task = None

    async def _tick_loop(self) -> None:
        try:
            while True:
                await self.tick()
                await asyncio.sleep(TICK_INTERVAL_S)
        except asyncio.CancelledError:
            pass

    def _start_timeout_monitor(self) -> None:
        if not self._timeout_task or self._timeout_task.done():
            self._timeout_task = asyncio.create_task(self._timeout_loop())

    def _stop_timeout_monitor(self) -> None:
        if self._timeout_task and not self._timeout_task.done():
            self._timeout_task.cancel()
            self._timeout_task = None

    async def _timeout_loop(self) -> None:
        """Monitor open decisions for wall-clock timeout expiry."""
        try:
            while self._decisions.get_open_decisions():
                await asyncio.sleep(0.5)
                now_ms = _time_mod.monotonic() * 1000
                pt = self._time.play_time_ms
                all_changes: list[StateChange] = []
                for d in list(self._decisions.get_open_decisions()):
                    if d.timeout_ms <= 0:
                        continue
                    if (now_ms - d.opened_at_rt_ms) < d.timeout_ms:
                        continue
                    # Auto-submit worst option via game mode
                    auto_id = self._config.game_mode.on_decision_timeout(
                        d.id,
                        d.options,
                    )
                    selected_ids = [auto_id] if auto_id else []
                    close_change = self._decisions.close_decision(
                        d.id,
                        current_pt_ms=pt,
                        selected_option_ids=selected_ids,
                    )
                    if close_change:
                        all_changes.append(close_change)
                    # Apply scoring via v2
                    selected_opts = [o for o in d.options if o["id"] in selected_ids]
                    template = self.find_decision_template(d.id)
                    forced_ids = template.forced_option_ids if template else []
                    extra = self._config.game_mode.on_decision_closed_v2(
                        d.id,
                        selected_opts,
                        d.options,
                        forced_option_ids=forced_ids or None,
                    )
                    all_changes.extend(extra)
                    # Apply system effects from selected options
                    all_changes.extend(self._apply_system_effects(selected_opts))
                    # Chain to next decision
                    next_id = self._config.game_mode.get_next_decision_id(d.id)
                    if next_id:
                        nt = self.find_decision_template(next_id)
                        if nt:
                            timeout_ms = self._config.game_mode.get_decision_time_ms(
                                int(nt.timeout_ms),
                            )
                            opened = self._decisions.open_decision(
                                id=nt.id,
                                event_id=None,
                                issue_id=nt.issue_id,
                                title=nt.title,
                                description=nt.description,
                                question_type=nt.question_type,
                                options=nt.options,
                                completion_mode=nt.completion_mode,
                                target_roles=nt.target_roles,
                                timeout_ms=timeout_ms,
                                max_selections=nt.max_selections,
                                current_pt_ms=pt,
                            )
                            all_changes.append(opened)
                if all_changes and self._on_state_change:
                    await self._on_state_change(all_changes)
                if not self._decisions.get_open_decisions():
                    if self._config.game_mode.requires_gm():
                        await self.resume()
                    break
        except asyncio.CancelledError:
            pass

    def _apply_system_effects(
        self, selected_options: list[DecisionOptionSnapshot],
    ) -> list[SystemStateChange]:
        """Apply system_effects from selected options via SystemManager."""
        out: list[SystemStateChange] = []  # TODO: targets_system needs submission data plumbing
        for opt in selected_options:
            for fx in opt["system_effects"]:
                if fx["power_state"] is not None:
                    if c := self._systems.set_power(fx["system_id"], fx["power_state"]):
                        out.append(c)
                if fx["operational_state"] is not None:
                    if c := self._systems.set_operational(fx["system_id"], fx["operational_state"]):
                        out.append(c)
        return out

    def _phase_change(self, action: str) -> PhaseChange:
        return {
            "type": "phase_change",
            "action": action,
            "phase": self._phase.value,
            "time": self._time.snapshot(),
        }

"""Schedules and manages inject (event) lifecycle transitions.

Domain term: "inject". Code uses "event" throughout.
Also known as: InjectScheduler, inject scheduler.

Injects progress through: scheduled -> pending -> running -> completed/cancelled.
Injects can have dependencies on other injects and can trigger defects (issues).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import StrEnum

from engine.state_changes import EventChange, EventSnapshot


class EventLifecycle(StrEnum):
    SCHEDULED = "scheduled"
    PENDING = "pending"
    RUNNING = "running"
    PAUSED = "paused"
    COMPLETED = "completed"
    CANCELLED = "cancelled"


class EventType(StrEnum):
    INFORMATIONAL = "informational"
    OPERATIONAL = "operational"
    DECISION = "decision"


VALID_TRANSITIONS: dict[EventLifecycle, set[EventLifecycle]] = {
    EventLifecycle.SCHEDULED: {EventLifecycle.PENDING, EventLifecycle.CANCELLED},
    EventLifecycle.PENDING: {EventLifecycle.RUNNING, EventLifecycle.CANCELLED},
    EventLifecycle.RUNNING: {
        EventLifecycle.PAUSED,
        EventLifecycle.COMPLETED,
        EventLifecycle.CANCELLED,
    },
    EventLifecycle.PAUSED: {EventLifecycle.RUNNING, EventLifecycle.CANCELLED},
    EventLifecycle.COMPLETED: set(),
    EventLifecycle.CANCELLED: set(),
}


@dataclass
class ScheduledEvent:
    """Runtime representation of an inject (event) during exercise execution."""

    id: str
    title: str
    description: str
    event_type: EventType
    scheduled_pt_ms: float
    duration_ms: float | None = None
    dependencies: list[str] = field(default_factory=list)
    triggered_issues: list[str] = field(default_factory=list)
    lifecycle: EventLifecycle = EventLifecycle.SCHEDULED
    started_at_pt_ms: float | None = None
    completed_at_pt_ms: float | None = None
    target_roles: list[str] = field(default_factory=list)
    role_descriptions: dict[str, str] = field(default_factory=dict)


class EventScheduler:
    """Manages inject (event) scheduling and lifecycle transitions.

    Also known as: InjectScheduler.
    """

    def __init__(self) -> None:
        self._events: dict[str, ScheduledEvent] = {}

    @property
    def events(self) -> dict[str, ScheduledEvent]:
        return self._events

    def load_events(self, events: list[ScheduledEvent]) -> None:
        """Load events from a scenario definition."""
        self._events = {e.id: e for e in events}

    def clear(self) -> None:
        self._events.clear()

    def tick(self, current_pt_ms: float) -> list[EventChange]:
        """Check all events and apply lifecycle transitions.

        Returns a list of state change dicts for broadcasting.
        """
        changes: list[EventChange] = []

        for event in self._events.values():
            if event.lifecycle == EventLifecycle.SCHEDULED:
                if self._should_activate(event, current_pt_ms):
                    self._transition(event, EventLifecycle.PENDING)
                    changes.append(self._change(event, "activated"))

            elif event.lifecycle == EventLifecycle.PENDING:
                self._transition(event, EventLifecycle.RUNNING)
                event.started_at_pt_ms = current_pt_ms
                changes.append(self._change(event, "started"))

            elif event.lifecycle == EventLifecycle.PAUSED:
                pass  # paused events do not tick

            elif event.lifecycle == EventLifecycle.RUNNING and event.duration_ms:
                if event.started_at_pt_ms is not None:
                    elapsed = current_pt_ms - event.started_at_pt_ms
                    if elapsed >= event.duration_ms:
                        self._transition(event, EventLifecycle.COMPLETED)
                        event.completed_at_pt_ms = current_pt_ms
                        changes.append(self._change(event, "completed"))

        return changes

    def force_trigger(self, event_id: str, current_pt_ms: float) -> EventChange | None:
        """GM manually triggers an event regardless of schedule."""
        event = self._events.get(event_id)
        if not event:
            return None
        if event.lifecycle in {EventLifecycle.COMPLETED, EventLifecycle.CANCELLED}:
            return None
        # GM override — bypass normal transition rules
        event.lifecycle = EventLifecycle.RUNNING
        event.started_at_pt_ms = current_pt_ms
        return self._change(event, "force_triggered")

    def cancel_event(self, event_id: str) -> EventChange | None:
        """GM cancels an event."""
        event = self._events.get(event_id)
        if not event:
            return None
        if event.lifecycle in {EventLifecycle.COMPLETED, EventLifecycle.CANCELLED}:
            return None
        self._transition(event, EventLifecycle.CANCELLED)
        return self._change(event, "cancelled")

    def complete_event(self, event_id: str, current_pt_ms: float) -> EventChange | None:
        """GM manually completes a running event."""
        event = self._events.get(event_id)
        if not event or event.lifecycle != EventLifecycle.RUNNING:
            return None
        self._transition(event, EventLifecycle.COMPLETED)
        event.completed_at_pt_ms = current_pt_ms
        return self._change(event, "completed")

    def pause_event(self, event_id: str) -> EventChange | None:
        """GM pauses a running event. Preserves elapsed time."""
        event = self._events.get(event_id)
        if not event or event.lifecycle != EventLifecycle.RUNNING:
            return None
        self._transition(event, EventLifecycle.PAUSED)
        return self._change(event, "paused")

    def resume_event(
        self,
        event_id: str,
        current_pt_ms: float,
    ) -> EventChange | None:
        """GM resumes a paused event. Adjusts started_at to preserve elapsed."""
        event = self._events.get(event_id)
        if not event or event.lifecycle != EventLifecycle.PAUSED:
            return None
        self._transition(event, EventLifecycle.RUNNING)
        return self._change(event, "resumed")

    def delay_event(
        self,
        event_id: str,
        delay_ms: float,
    ) -> EventChange | None:
        """GM delays a scheduled event by adding to its scheduled time."""
        event = self._events.get(event_id)
        if not event or event.lifecycle != EventLifecycle.SCHEDULED:
            return None
        event.scheduled_pt_ms += delay_ms
        return self._change(event, "delayed")

    def skip_event(self, event_id: str) -> EventChange | None:
        """GM skips (cancels) a scheduled/pending event."""
        event = self._events.get(event_id)
        if not event:
            return None
        if event.lifecycle in {EventLifecycle.COMPLETED, EventLifecycle.CANCELLED}:
            return None
        self._transition(event, EventLifecycle.CANCELLED)
        return self._change(event, "skipped")

    def get_triggered_issues(self, event_id: str) -> list[str]:
        """Get issue IDs triggered by a completed event."""
        event = self._events.get(event_id)
        if not event:
            return []
        return event.triggered_issues

    def _should_activate(
        self,
        event: ScheduledEvent,
        current_pt_ms: float,
    ) -> bool:
        """Check if event should transition from scheduled to pending."""
        if current_pt_ms < event.scheduled_pt_ms:
            return False
        # Check dependencies are completed
        for dep_id in event.dependencies:
            dep = self._events.get(dep_id)
            if not dep or dep.lifecycle != EventLifecycle.COMPLETED:
                return False
        return True

    @staticmethod
    def _transition(event: ScheduledEvent, target: EventLifecycle) -> None:
        allowed = VALID_TRANSITIONS.get(event.lifecycle, set())
        if target not in allowed:
            return
        event.lifecycle = target

    @staticmethod
    def _change(event: ScheduledEvent, action: str) -> EventChange:
        return {
            "type": "event_change",
            "event_id": event.id,
            "action": action,
            "lifecycle": event.lifecycle.value,
            "title": event.title,
            "target_roles": event.target_roles,
            "role_descriptions": event.role_descriptions,
        }

    def snapshot(self) -> list[EventSnapshot]:
        """Return all events as serializable dicts."""
        return [
            EventSnapshot(
                id=e.id,
                title=e.title,
                description=e.description,
                event_type=e.event_type.value,
                scheduled_pt_ms=e.scheduled_pt_ms,
                duration_ms=e.duration_ms,
                dependencies=e.dependencies,
                triggered_issues=e.triggered_issues,
                lifecycle=e.lifecycle.value,
                started_at_pt_ms=e.started_at_pt_ms,
                completed_at_pt_ms=e.completed_at_pt_ms,
                target_roles=e.target_roles,
                role_descriptions=e.role_descriptions,
            )
            for e in self._events.values()
        ]

"""REST endpoints for engine entity actions (events, issues, decisions).

Split from engine_router.py to stay under the 250-line limit.
"""

from __future__ import annotations

from fastapi import APIRouter, HTTPException, status
from pydantic import BaseModel, Field

from engine.exercise_engine import ExerciseEngine
from engine.session_store import session_store
from engine.state_changes import EventChange, IssueChange, StateChange

router = APIRouter(prefix="/api/exercises/{exercise_id}/engine", tags=["engine"])


class DelayRequest(BaseModel):
    delay_ms: float = Field(..., gt=0)


def _get_engine(exercise_id: int) -> ExerciseEngine:
    """Retrieve engine or raise 404."""
    engine = session_store.get(exercise_id)
    if engine is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"No active engine for exercise {exercise_id}",
        )
    return engine


def _or_404[T: StateChange](result: T | None, detail: str) -> T:
    if result is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=detail)
    return result


# ── Event actions ────────────────────────────────────────────────────────


@router.post("/events/{event_id}/trigger", operation_id="triggerEvent")
async def trigger_event(exercise_id: int, event_id: str) -> EventChange:
    engine = _get_engine(exercise_id)
    pt = engine.time_manager.play_time_ms
    return _or_404(
        engine.event_scheduler.force_trigger(event_id, pt),
        f"Event {event_id} not found or not triggerable",
    )


@router.post("/events/{event_id}/cancel", operation_id="cancelEvent")
async def cancel_event(exercise_id: int, event_id: str) -> EventChange:
    return _or_404(
        _get_engine(exercise_id).event_scheduler.cancel_event(event_id),
        f"Event {event_id} not found or not cancellable",
    )


@router.post("/events/{event_id}/complete", operation_id="completeEvent")
async def complete_event(exercise_id: int, event_id: str) -> EventChange:
    engine = _get_engine(exercise_id)
    pt = engine.time_manager.play_time_ms
    return _or_404(
        engine.event_scheduler.complete_event(event_id, pt),
        f"Event {event_id} not found or not completable",
    )


@router.post("/events/{event_id}/pause", operation_id="pauseEvent")
async def pause_event(exercise_id: int, event_id: str) -> EventChange:
    return _or_404(
        _get_engine(exercise_id).event_scheduler.pause_event(event_id),
        f"Event {event_id} not found or not pausable",
    )


@router.post("/events/{event_id}/resume", operation_id="resumeEvent")
async def resume_event(exercise_id: int, event_id: str) -> EventChange:
    engine = _get_engine(exercise_id)
    pt = engine.time_manager.play_time_ms
    return _or_404(
        engine.event_scheduler.resume_event(event_id, pt),
        f"Event {event_id} not found or not resumable",
    )


@router.post("/events/{event_id}/delay", operation_id="delayEvent")
async def delay_event(
    exercise_id: int,
    event_id: str,
    body: DelayRequest,
) -> EventChange:
    return _or_404(
        _get_engine(exercise_id).event_scheduler.delay_event(
            event_id,
            body.delay_ms,
        ),
        f"Event {event_id} not found or not delayable",
    )


@router.post("/events/{event_id}/skip", operation_id="skipEvent")
async def skip_event(exercise_id: int, event_id: str) -> EventChange:
    return _or_404(
        _get_engine(exercise_id).event_scheduler.skip_event(event_id),
        f"Event {event_id} not found or not skippable",
    )


# ── Issue actions ────────────────────────────────────────────────────────


@router.post("/issues/{issue_id}/activate", operation_id="activateIssue")
async def activate_issue(exercise_id: int, issue_id: str) -> IssueChange:
    engine = _get_engine(exercise_id)
    pt = engine.time_manager.play_time_ms
    return _or_404(
        engine.issue_manager.manual_activate(issue_id, pt),
        f"Issue {issue_id} not found or not activatable",
    )


@router.post("/issues/{issue_id}/mitigate", operation_id="mitigateIssue")
async def mitigate_issue(exercise_id: int, issue_id: str) -> IssueChange:
    return _or_404(
        _get_engine(exercise_id).issue_manager.mitigate(issue_id),
        f"Issue {issue_id} not found or not mitigatable",
    )


@router.post("/issues/{issue_id}/resolve", operation_id="resolveIssue")
async def resolve_issue(exercise_id: int, issue_id: str) -> IssueChange:
    engine = _get_engine(exercise_id)
    pt = engine.time_manager.play_time_ms
    return _or_404(
        engine.issue_manager.resolve(issue_id, pt),
        f"Issue {issue_id} not found or not resolvable",
    )


@router.post("/issues/{issue_id}/release", operation_id="releaseIssue")
async def release_issue(exercise_id: int, issue_id: str) -> IssueChange:
    return _or_404(
        _get_engine(exercise_id).issue_manager.release_to_players(issue_id),
        f"Issue {issue_id} not found or not releasable",
    )


# ── Decision actions ─────────────────────────────────────────────────────


@router.get("/decisions", operation_id="getOpenDecisions")
async def get_open_decisions(exercise_id: int) -> list[dict[str, object]]:
    engine = _get_engine(exercise_id)
    return [
        {
            "id": d.id,
            "event_id": d.event_id,
            "title": d.title,
            "question_type": d.question_type,
            "options": d.options,
            "target_roles": d.target_roles,
            "status": d.status,
        }
        for d in engine.decision_manager.get_open_decisions()
    ]

    # close_decision endpoint has been consolidated into engine_router.py
    # to support scoring, turn chaining, and forced card enforcement.


# ── Context ──────────────────────────────────────────────────────────────


@router.get("/context", operation_id="getEngineContext")
async def get_engine_context(exercise_id: int) -> dict[str, object]:
    engine = _get_engine(exercise_id)
    ctx = engine.config.context
    return {
        "title": ctx.title,
        "description": ctx.description,
        "briefing": ctx.briefing,
        "objectives": ctx.objectives,
        "rules": ctx.rules,
        "default_time_factor": engine.config.time_factor,
    }

